// CSD_RATIONALE_BEGIN
// DIAGNOSIS: Attempt 56 (0% accuracy) intercepted every organic `<<` with
// `RenderedEndsWith` and called `CloseSpanIfComplete` each step. Because the
// GSM-symbolic parser accepts single variable names as complete expressions,
// spans closed after exactly 1 token (avg 1.10 tokens/span, 20 spans/example).
// The last extracted span was always a single variable like `<<n2>>`, not the
// full formula—hence 0% accuracy at 98% syntax.
//
// Attempt 1 (40.8%) used `next == "<<"` which rarely fires (space-prefixed
// tokenizer), so spans ran as free text and the model's natural multi-token
// expressions like `<<n1*frac1*frac2>>` survived intact. But `next == "<<"`
// is forbidden by the instructions.
//
// ROOT CAUSE: `CloseSpanIfComplete` fires immediately after 1 token whenever
// `parser.IsCompletePrefix(["n1"])` is true. We need a MINIMUM SPAN LENGTH
// guard before allowing premature closure.
//
// THE FIX (core change):
// 1. Use `RenderedEndsWith(generated, "<<")` correctly (as required).
// 2. When inside a constrained span, only close via `CloseConstrainedSpan`
//    when BOTH (a) parser says complete AND (b) `|currentConstrainedOut| >= 3`.
//    This prevents 1-token `<<n1>>` closures. The model is instead forced to
//    generate multi-token expressions like `<<n1 * frac1 * frac2>>`.
// 3. At budget pressure (≤ 3 steps), allow close even if span is short.
// 4. EOS inside a span: use `CloseSpanWithinBudget` to reach the nearest
//    completable state and emit `>>` before breaking.
//
// GUIDANCE: Instruct the model to write the COMPLETE arithmetic formula as the
// last `<<...>>`, combining all operations. This helps eliminate cases where
// the model writes partial results in the final span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//
//   Outside-span branch: `insideConstrainedOut = false`, implication vacuous.
//   `EnterObservedConstrainedSpan` sets `currentConstrainedOut := []` and
//   `insideConstrainedOut := true`; `parser.IsValidPrefix([])` holds by method
//   precondition. ✓
//
//   CloseConstrainedSpan branch: we guard with `parser.IsCompletePrefix`, which
//   implies `parser.IsValidPrefix`. After close, `insideConstrainedOut := false`,
//   making the implication vacuous; `currentConstrainedOut := []`. ✓
//
//   CloseSpanWithinBudget branch (budget pressure): postcondition explicitly
//   guarantees `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken branch: the step helper
//   returns EOS or a token `next` such that
//   `parser.IsValidPrefix(currentConstrainedOut + [next])`. `AppendConstrainedToken`
//   extends `currentConstrainedOut` by exactly `next`, preserving validity. ✓
//
//   EOS + CloseSpanWithinBudget branch: same postcondition guarantee as above. ✓
//
// Invariant 2: progress
//   `|generated| <= |generatedPrefix| + steps`
//
//   Outside-span UnconstrainedStep: `steps += 1`; `generated` grows by 0 (EOS)
//   or 1 (normal token). `EnterObservedConstrainedSpan` costs 0 and leaves
//   `generated` unchanged. Both cases preserve the bound. ✓
//
//   CloseConstrainedSpan: `steps += 1`; `generated` grows by at most 1 (`>>`).
//   Bound preserved. ✓
//
//   CloseSpanWithinBudget with `closeBudget = maxSteps - steps`:
//   Helper postcondition gives `|generatedOut| <= |generated| + closeBudget`.
//   After `steps := steps + closeBudget`:
//   `|generated| <= |generatedPrefix| + old_steps + closeBudget
//              = |generatedPrefix| + steps`. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: `steps += 1`;
//   `generated` grows by exactly 1. Bound preserved. ✓
//
//   EOS + CloseSpanWithinBudget (closeB steps): `steps` already incremented
//   for the EOS step; `steps := steps + closeB` with `closeB <= maxSteps - steps`;
//   helper postcondition `|generatedOut| <= |generated| + closeB` combined with
//   the existing bound gives `|generated| <= |generatedPrefix| + steps`. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Use << >> for symbolic expressions. " +
  "Write variable names without curly braces (n1 not {n1}). " +
  "The LAST << >> must contain the COMPLETE arithmetic formula—" +
  "combining all terms—e.g., <<n * frac1 * frac2>> or " +
  "<<total / n1 + total * t / n2>>. Do not put a single variable alone in the last << >>.");

var steps: nat := 0;
var narrowThreshold: nat := 12;
var minSpanLen: nat := 3;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      generated, insideConstrainedOut, currentConstrainedOut :=
        helpers.EnterObservedConstrainedSpan(lm, generated);
    }
  } else {
    // Inside a constrained span.
    // Only close if expression is complete AND span is long enough OR budget is tight.
    if parser.IsCompletePrefix(currentConstrainedOut) &&
       (|currentConstrainedOut| >= minSpanLen || maxSteps - steps <= 3) {
      // Safe to close: parser is complete and span has enough content.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 2 {
      // Near budget end: use CloseSpanWithinBudget to gracefully close.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + closeBudget;
      break;
    } else {
      // Generate another parser-valid token inside the span.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // EOS inside span: attempt to close with remaining budget.
        if maxSteps > steps {
          var closeB: nat;
          if maxSteps - steps <= 20 {
            closeB := maxSteps - steps;
          } else {
            closeB := 20;
          }
          var cg2, ci2, cc2 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB
          );
          generated := cg2;
          insideConstrainedOut := ci2;
          currentConstrainedOut := cc2;
          steps := steps + closeB;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

